[metadata] {"type": "create", "filePath": "/app/output/final_report.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Student Performance Analytics Report — Bangladesh</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js"></script>
<style>
  :root {
    --primary: #1a3a5c;
    --primary-light: #2a5a8c;
    --accent: #e67e22;
    --accent-light: #f39c49;
    --bg: #f5f7fa;
    --card: #ffffff;
    --text: #2c3e50;
    --text-light: #6c7a89;
    --green: #27ae60;
    --green-light: #eafaf1;
    --amber: #f39c12;
    --amber-light: #fef9e7;
    --red: #e74c3c;
    --red-light: #fdedec;
    --blue: #3498db;
    --blue-light: #ebf5fb;
    --border: #e1e8ed;
    --shadow: 0 2px 12px rgba(0,0,0,0.08);
    --radius: 10px;
  }
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body {
    font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.6;
    font-size: 15px;
  }
  .container { max-width: 1200px; margin: 0 auto; padding: 20px; }

  /* Header */
  .report-header {
    background: linear-gradient(135deg, var(--primary) 0%, var(--primary-light) 100%);
    color: white;
    padding: 48px 40px 36px;
    border-radius: var(--radius);
    margin-bottom: 28px;
    position: relative;
    overflow: hidden;
  }
  .report-header::before {
    content: '';
    position: absolute;
    top: -50%;
    right: -10%;
    width: 400px;
    height: 400px;
    background: rgba(255,255,255,0.04);
    border-radius: 50%;
  }
  .report-header h1 { font-size: 28px; font-weight: 700; margin-bottom: 8px; }
  .report-header .subtitle { font-size: 16px; opacity: 0.9; margin-bottom: 18px; }
  .report-header .meta { font-size: 13px; opacity: 0.75; display: flex; gap: 24px; flex-wrap: wrap; }
  .report-header .meta span { display: flex; align-items: center; gap: 6px; }

  /* Section */
  .section {
    background: var(--card);
    border-radius: var(--radius);
    box-shadow: var(--shadow);
    padding: 32px;
    margin-bottom: 24px;
  }
  .section-header {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 20px;
    padding-bottom: 14px;
    border-bottom: 2px solid var(--bg);
  }
  .section-number {
    background: var(--primary);
    color: white;
    width: 32px;
    height: 32px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 700;
    font-size: 14px;
    flex-shrink: 0;
  }
  .section h2 { font-size: 20px; font-weight: 700; color: var(--primary); }
  .section h3 { font-size: 16px; font-weight: 600; color: var(--primary); margin: 22px 0 12px; }
  .section p { margin-bottom: 12px; color: var(--text); }
  .section ul { margin: 0 0 12px 20px; }
  .section li { margin-bottom: 6px; }

  /* KPI Cards */
  .kpi-grid {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 16px;
    margin-bottom: 24px;
  }
  @media (max-width: 900px) { .kpi-grid { grid-template-columns: repeat(2, 1fr); } }
  .kpi-card {
    background: var(--card);
    border-radius: var(--radius);
    padding: 22px 18px;
    box-shadow: var(--shadow);
    text-align: center;
    border-top: 4px solid var(--primary);
    position: relative;
  }
  .kpi-card.green { border-top-color: var(--green); }
  .kpi-card.amber { border-top-color: var(--amber); }
  .kpi-card.red { border-top-color: var(--red); }
  .kpi-card.blue { border-top-color: var(--blue); }
  .kpi-value {
    font-size: 32px;
    font-weight: 800;
    color: var(--primary);
    line-height: 1.2;
  }
  .kpi-card.green .kpi-value { color: var(--green); }
  .kpi-card.amber .kpi-value { color: var(--amber); }
  .kpi-card.red .kpi-value { color: var(--red); }
  .kpi-card.blue .kpi-value { color: var(--blue); }
  .kpi-unit { font-size: 16px; font-weight: 400; }
  .kpi-label {
    font-size: 12px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: var(--text-light);
    margin-top: 6px;
    font-weight: 600;
  }
  .kpi-desc {
    font-size: 11px;
    color: var(--text-light);
    margin-top: 4px;
    line-height: 1.4;
  }
  .kpi-indicator {
    display: inline-block;
    padding: 2px 8px;
    border-radius: 12px;
    font-size: 11px;
    font-weight: 600;
    margin-top: 8px;
  }
  .kpi-indicator.good { background: var(--green-light); color: var(--green); }
  .kpi-indicator.warn { background: var(--amber-light); color: var(--amber); }
  .kpi-indicator.bad { background: var(--red-light); color: var(--red); }
  .kpi-indicator.neutral { background: var(--blue-light); color: var(--blue); }

  /* Tables */
  table {
    width: 100%;
    border-collapse: collapse;
    margin: 14px 0;
    font-size: 14px;
  }
  th {
    background: var(--primary);
    color: white;
    padding: 10px 14px;
    text-align: left;
    font-weight: 600;
    font-size: 13px;
    text-transform: uppercase;
    letter-spacing: 0.3px;
  }
  td {
    padding: 10px 14px;
    border-bottom: 1px solid var(--border);
  }
  tr:nth-child(even) td { background: #fafbfc; }
  tr:hover td { background: var(--blue-light); }
  .num { text-align: right; font-variant-numeric: tabular-nums; }
  .highlight-best { background: var(--green-light) !important; font-weight: 600; }
  .highlight-worst { background: var(--red-light) !important; }

  /* Charts */
  .chart-container {
    position: relative;
    margin: 20px 0;
  }
  .chart-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
    margin: 20px 0;
  }
  @media (max-width: 768px) { .chart-row { grid-template-columns: 1fr; } }
  .chart-box {
    background: #fafbfc;
    border-radius: 8px;
    padding: 20px;
    border: 1px solid var(--border);
  }
  .chart-box h4 {
    font-size: 14px;
    font-weight: 600;
    color: var(--primary);
    margin-bottom: 14px;
    text-align: center;
  }
  canvas { max-width: 100%; }

  /* Heatmap */
  .heatmap-table td.heat { text-align: center; font-weight: 600; color: white; }
  .heat-1 { background: #e74c3c; }
  .heat-2 { background: #e67e22; }
  .heat-3 { background: #f1c40f; color: var(--text) !important; }
  .heat-4 { background: #2ecc71; }
  .heat-5 { background: #27ae60; }

  /* Callout */
  .callout {
    background: var(--blue-light);
    border-left: 4px solid var(--blue);
    padding: 16px 20px;
    border-radius: 0 8px 8px 0;
    margin: 18px 0;
    font-size: 14px;
  }
  .callout.warning {
    background: var(--amber-light);
    border-left-color: var(--amber);
  }
  .callout.success {
    background: var(--green-light);
    border-left-color: var(--green);
  }
  .callout strong { color: var(--primary); }

  /* Grid helpers */
  .stat-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 12px;
    margin: 14px 0;
  }
  .stat-box {
    background: #fafbfc;
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 14px;
    text-align: center;
  }
  .stat-box .val { font-size: 22px; font-weight: 700; color: var(--primary); }
  .stat-box .lbl { font-size: 11px; color: var(--text-light); text-transform: uppercase; margin-top: 2px; }

  /* Recommendation cards */
  .rec-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; margin: 14px 0; }
  .rec-card {
    background: #fafbfc;
    border: 1px solid var(--border);
    border-radius: 8px;
    padding: 18px;
    border-left: 4px solid var(--accent);
  }
  .rec-card h4 { font-size: 15px; font-weight: 600; color: var(--primary); margin-bottom: 8px; }
  .rec-card p { font-size: 13px; color: var(--text-light); margin: 0; }

  .toc { background: #fafbfc; border-radius: 8px; padding: 18px 24px; margin-bottom: 24px; border: 1px solid var(--border); }
  .toc h3 { font-size: 14px; margin-bottom: 10px; color: var(--primary); }
  .toc ol { margin: 0 0 0 20px; }
  .toc li { margin: 4px 0; }
  .toc a { color: var(--primary-light); text-decoration: none; font-size: 14px; }
  .toc a:hover { text-decoration: underline; }

  .footer {
    text-align: center;
    padding: 28px;
    color: var(--text-light);
    font-size: 12px;
    border-top: 1px solid var(--border);
    margin-top: 16px;
  }

  /* Badge */
  .badge {
    display: inline-block;
    padding: 2px 10px;
    border-radius: 12px;
    font-size: 12px;
    font-weight: 600;
  }
  .badge-green { background: var(--green-light); color: var(--green); }
  .badge-amber { background: var(--amber-light); color: var(--amber); }
  .badge-red { background: var(--red-light); color: var(--red); }

  @media print {
    body { font-size: 12px; }
    .container { max-width: 100%; padding: 10px; }
    .section { break-inside: avoid; box-shadow: none; border: 1px solid #ddd; }
    .kpi-grid { grid-template-columns: repeat(5, 1fr); }
  }
</style>
</head>
