<div class="container">

<!-- HEADER -->
<div class="report-header">
  <h1>Student Performance Analytics Report</h1>
  <p class="subtitle">Factors Influencing Academic Outcomes Across Districts in Bangladesh</p>
  <div class="meta">
    <span><strong>Dataset:</strong> 1,000 students</span>
    <span><strong>Scope:</strong> 8 divisions</span>
    <span><strong>Examinations:</strong> SSC &amp; HSC</span>
