<!-- TABLE OF CONTENTS -->
<div class="toc">
  <h3>Report Contents</h3>
  <ol>
    <li><a href="#sec1">Student Demographic Overview</a></li>
    <li><a href="#sec2">Academic Performance Analysis</a></li>
