    </div>
    <div class="chart-box">
      <h4>Performance Classification (HSC)</h4>
      <canvas id="chartHscClass" height="240"></canvas>
    </div>
  </div>

  <table>
    <thead>
      <tr><th>Classification</th><th>GPA Range</th><th class="num">Previous GPA</th><th class="num">SSC</th><th class="num">HSC</th></tr>
